.ds-amount-table { font-family: "Public Sans", sans-serif; font-size: 15px; font-weight: 400; line-height: 1.55; color: var(--ink, #172a43); } .ds-amount-table { border-collapse: collapse; width: 100%; table-layout: fixed; } .ds-amount-table thead th { text-align: left; font-size: 10.5px; font-weight: 550; color: var(--muted, #5b6b80); padding: 0 0 10px; border-bottom: 1px solid #a8bbd4; } .ds-amount-table thead th.ds-quantity-heading { text-align: right; width: 180px; } .ds-amount-table tbody tr { border-bottom: 1px solid var(--line, #d6e0ed); } .ds-amount-table tbody th { text-align: left; padding: 15px 12px 15px 0; font-size: 13.65px; font-weight: 500; line-height: 1.45; overflow-wrap: anywhere; } .ds-amount-table small { display: block; font-size: 9.75px; color: var(--muted, #5b6b80); font-weight: 400; margin-top: 4px; letter-spacing: 0.015em; font-variant-numeric: tabular-nums; } .ds-amount-cell { text-align: right; white-space: nowrap; padding: 12px 0 12px 10px; font-variant-numeric: tabular-nums; line-height: 1.2; } .ds-amount-label { display: none; } .ds-amount-value { display: inline-flex; align-items: baseline; max-width: 100%; } .ds-amount-number { display: inline-block; min-width: 60px; animation: ds-quantity-change 420ms cubic-bezier(0.16, 1, 0.3, 1); font-size: 18.75px; font-weight: 600; letter-spacing: -0.02em; } .ds-amount-unit { display: inline-block; width: 38px; text-align: left; margin-left: 12px; color: var(--muted, #5b6b80); font-size: 11.55px; } @keyframes ds-quantity-change { from {
    background-color: #c9deff;
    filter: blur(0.35px);
  }
  to {
    background-color: transparent;
    filter: blur(0);
  } } @media (max-width: 860px) { .ds-amount-table thead th.ds-quantity-heading { width: 142px; } .ds-amount-number { font-size: 16.95px; } .ds-amount-unit { margin-left: 8px; width: 25px; font-size: 10.95px; } .ds-amount-table tbody th { font-size: 12.45px; } } @media (max-width: 640px) { .ds-amount-table, .ds-amount-table tbody { display: block; width: 100%; } .ds-amount-table thead { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; } .ds-amount-table tbody tr { display: grid; grid-template-columns: minmax(0, 1fr); gap: 9px; padding: 14px 0; } .ds-amount-table tbody th { display: block; padding: 0; font-size: 12.15px; } .ds-amount-table small { font-size: 8.85px; } .ds-amount-cell { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 5px 12px; min-width: 0; white-space: normal; padding: 0; } .ds-amount-label { display: block; color: var(--muted, #5b6b80); font-size: 9.75px; } .ds-amount-value { min-width: 0; margin-left: auto; } .ds-amount-number { font-size: 17.4px; min-width: 0; overflow-wrap: anywhere; } .ds-amount-unit { flex: 0 0 22px; font-size: 10.2px; width: 22px; margin-left: 8px; } } @media (prefers-reduced-motion: reduce) { .ds-amount-number { animation: none !important; transition: none !important; scroll-behavior: auto !important; } }
